import subprocess,re,json
unit="prediction-a2z-v4-model@A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2.service"
p=subprocess.run(["journalctl","--user","-u",unit,"--since","2026-10-07 21:12:30","--no-pager"],capture_output=True,text=True)
rows=[]
for line in (p.stdout or "").splitlines():
    if "A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2" not in line and "SUPERVISOR_STATE" not in line:
        continue
    rec={}
    m=re.match(r"^([A-Z][a-z]{2} \d{2} \d{2}:\d{2}:\d{2}) ",line)
    if m: rec["time"]=m.group(1)
    m=re.search(r'"state"\s*:\s*"([^"]+)"',line)
    if m: rec["state"]=m.group(1)
    m=re.search(r'"reason"\s*:\s*"([^"]+)"',line)
    if m: rec["reason"]=m.group(1)
    m=re.search(r'"attempt"\s*:\s*(\d+)',line)
    if m: rec["attempt"]=int(m.group(1))
    m=re.search(r'"checkpoint"\s*:\s*"([^"]+)"',line)
    if m: rec["checkpoint"]=m.group(1)
    m=re.search(r'"retry_at"\s*:\s*([0-9.]+)',line)
    if m: rec["retry_at"]=float(m.group(1))
    if "Started prediction-a2z-v4-model@" in line: rec["event"]="STARTED"
    if "Deactivated successfully" in line: rec["event"]="DEACTIVATED"
    if "Main process exited" in line: rec["event"]="MAIN_EXIT"
    if "Failed with result" in line: rec["event"]="FAILED"
    if rec: rows.append(rec)
print("ERROR_CLASS=R4P2_RESUME_SEQUENCE",flush=True)
print("ERROR="+json.dumps(rows[-20:],separators=(",",":"),sort_keys=True),flush=True)
raise SystemExit(1)
